// Biblioteca inicial de ejercicios (gimnasio funcional, nombres como se usan en España). Solo se usa para llenar una
// base de datos vacía: a partir de ahí los ejercicios son filas normales que el equipo edita y borra.
// Los ids son slugs estables: no cambiarlos, las rutinas guardadas los referencian.
// Etiquetas: músculo principal (el primero de la lista), otros músculos que trabajan y tipo. Ver config/exerciseTags.ts.

import type { ExerciseType, LibraryExercise, MeasureType, MuscleGroup } from '@/types'

interface Extra {
  aliases?: string[]
  perSide?: boolean
}

function x(
  id: string,
  name: string,
  [muscle, ...secondaryMuscles]: [MuscleGroup, ...MuscleGroup[]],
  type: ExerciseType,
  equipment: string[],
  defaultMeasure: MeasureType = 'reps',
  extra: Extra = {},
): LibraryExercise {
  const ex: LibraryExercise = { id, name, muscle, type, equipment, defaultMeasure }
  if (secondaryMuscles.length) ex.secondaryMuscles = secondaryMuscles
  if (extra.aliases && extra.aliases.length) ex.aliases = extra.aliases
  if (extra.perSide) ex.perSide = true
  return ex
}

